  function makeNode(kind,x,z,i){const hp={tree:75,rock:90,fiber:45,ore:120,crystal:95,berry:35}[kind]||50;return{id:'node-'+i,kind:kind,x:x,z:z,hp:hp,maxHp:hp,active:true,respawn:0}}
  function createNodes(){return NODE_LAYOUT.map((v,i)=>makeNode(v[0],v[1],v[2],i))}
  function makeWild(type,x,z,i){const d=CREATURES[type];return{id:'wild-'+type+'-'+i,type:type,x:x,z:z,homeX:x,homeZ:z,yaw:Math.random()*TAU,hp:d.hp,maxHp:d.hp,anim:'idle',animT:Math.random(),animLock:0,flash:0,attackCd:1.4+Math.random()*2,think:Math.random(),dead:false,deathTimer:0,respawn:0}}
  function createWild(){return[
    makeWild('embermite',-31,-18,0),makeWild('mossclaw',-52,10,1),makeWild('gloomfin',-68,-37,2),makeWild('glintling',-20,34,3),
    makeWild('embermite',18,-30,4),makeWild('mossclaw',39,-14,5),makeWild('gloomfin',58,-42,6),makeWild('glintling',75,-19,7),
    makeWild('embermite',46,35,8),makeWild('mossclaw',70,48,9),makeWild('gloomfin',28,54,10),makeWild('glintling',-5,-48,11),
    makeWild('ironroot',76,42,12)
  ]}
  function biomeAt(x,z){return WORLD.biomes.find(b=>x>=b.minX&&x<=b.maxX&&z>=b.minZ&&z<=b.maxZ)||WORLD.biomes[0]}
  function resourceAmount(kind){return{tree:{wood:8},rock:{stone:7},fiber:{fiber:6},ore:{ore:5,stone:2},crystal:{crystal:3},berry:{berry:5}}[kind]||{}}
  function addInv(s,gain){Object.keys(gain).forEach(k=>{s.inv[k]=(s.inv[k]||0)+(gain[k]||0)})}
  function hasCost(s,cost){return Object.keys(cost).every(k=>(s.inv[k]||0)>=cost[k])}
  function spend(s,cost){Object.keys(cost).forEach(k=>{s.inv[k]-=cost[k]})}
  function costText(cost){return Object.keys(cost).map(k=>cost[k]+' '+k).join(' • ')}

  function initState(){
    const p=readSave(),s={save:p,level:p.level,xp:p.xp,day:p.day,dayClock:p.dayClock,hunger:p.hunger,hydration:p.hydration,energy:p.energy,
      inv:p.inventory,roster:p.roster,activeCreatureId:p.activeCreatureId||null,base:p.base||null,workers:p.workers||[],tutorial:p.tutorial||{},
      player:{x:WORLD.spawn[0],z:WORLD.spawn[1],yaw:0,hp:p.hp,maxHp:320,energy:100,anim:'idle',animT:0,animLock:0,flash:0,attackCd:0,dodgeCd:0},
      ally:{type:'oriel',x:-2,z:14,yaw:0,hp:230,maxHp:230,anim:'idle',animT:0,animLock:0,flash:0,attackCd:1.2,deployed:true},
      world:{nodes:createNodes(),wild:createWild(),structures:(p.structures||[]).filter(x=>x&&x.type&&Number.isFinite(x.x)&&Number.isFinite(x.z))},
      projectiles:[],captureOrbs:[],particles:[],floaters:[],feed:[],dialogue:null,dialogueIndex:0,paused:false,buildOpen:false,craftOpen:false,
      joy:{active:false,x:0,y:0},lookYaw:0,lookPitch:.52,cameraDistance:9,keys:Object.create(null),touchLook:null,last:now(),clock:0,survivalClock:0,workerClock:0,saveClock:0,interactText:'E • INTERAGIR'};
    s.player.hp=clamp(Number(p.hp)||s.player.maxHp,1,s.player.maxHp);s.player.energy=s.energy;return s
  }

  function structureNear(s,type,range){return s.world.structures.find(b=>b.type===type&&dist(b.x,b.z,s.player.x,s.player.z)<(range||3))}
  function blocked(s,x,z,r){if(x<WORLD.bounds.minX+1+r||x>WORLD.bounds.maxX-1-r||z<WORLD.bounds.minZ+1+r||z>WORLD.bounds.maxZ-1-r)return true;return s.world.structures.some(b=>b.type==='wall'&&dist(b.x,b.z,x,z)<1.55+r)}
  function cameraVectors(s){const y=s.lookYaw,p=s.lookPitch;return{forward:{x:Math.sin(y)*Math.cos(p),y:-Math.sin(p),z:Math.cos(y)*Math.cos(p)},right:{x:Math.cos(y),y:0,z:-Math.sin(y)}}}
  function move(s,dx,dz,dt=.016){const l=Math.hypot(dx,dz);if(!l)return;const sp=s.player.anim==='run'?7.9:6.1,nx=s.player.x+dx/l*sp*dt,nz=s.player.z+dz/l*sp*dt;if(!blocked(s,nx,s.player.z,.45))s.player.x=nx;if(!blocked(s,s.player.x,nz,.45))s.player.z=nz;s.player.yaw=Math.atan2(dx,dz);playAnim(s.player,s.player.anim==='run'?'run':'walk',0)}
  function dodge(s){if(s.player.dodgeCd>0||s.player.energy<18)return;s.player.energy-=18;s.player.dodgeCd=.65;const v=cameraVectors(s).forward,nx=s.player.x+v.x*4,nz=s.player.z+v.z*4;if(!blocked(s,nx,nz,.45)){s.player.x=nx;s.player.z=nz}playAnim(s.player,'dodge',.48);burst(s,s.player.x,.3,s.player.z,[.35,.90,1],8)}

  function nearestAt(list,x,z,r){let best=null,bd=r;for(const e of list){if(e.dead)continue;const d=dist(e.x,e.z,x,z);if(d<bd){best=e;bd=d}}return best}
  function nearestWild(s,range=9){return nearestAt(s.world.wild,s.player.x,s.player.z,range)}
  function nearestNode(s,range=3.7){let best=null,bd=range;for(const n of s.world.nodes){if(!n.active)continue;const d=dist(n.x,n.z,s.player.x,s.player.z);if(d<bd){bd=d;best=n}}return best}
  function nearestNpc(s,range=4.3){let best=null,bd=range;for(const n of NPCS){const d=dist(n.x,n.z,s.player.x,s.player.z);if(d<bd){bd=d;best=n}}return best}

  function damageWild(s,e,n){if(!e||e.dead)return;e.hp-=n;e.flash=.12;playAnim(e,'hit',.18);floatText(s,'-'+Math.round(n),e.x,2.2,e.z,[1,.38,.58]);burst(s,e.x,.75,e.z,[1,.30,.30],4);if(e.hp<=0){e.hp=0;e.dead=true;e.deathTimer=.72;playAnim(e,'death',.70);xp(s,e.type==='ironroot'?240:24);addInv(s,e.type==='ironroot'?{ore:20,crystal:8}:{essence:1});feed(s,e.type==='ironroot'?'Ironroot derrotado • +minério':'Criatura derrotada • +essência');saveProgress(s)}}
  function damagePlayer(s,n){if(s.player.dodgeCd>.30)return;s.player.hp=clamp(s.player.hp-n,0,s.player.maxHp);s.player.flash=.12;playAnim(s.player,'hit',.18);floatText(s,'-'+Math.round(n),s.player.x,2.15,s.player.z,[1,.30,.45]);if(s.player.hp<=0){s.player.hp=s.player.maxHp;s.player.x=WORLD.spawn[0];s.player.z=WORLD.spawn[1];s.hunger=55;s.hydration=55;feed(s,'Você desmaiou e voltou ao acampamento.')}} 
  function basicAttack(s){if(s.paused||s.player.attackCd>0)return;s.player.attackCd=.34;playAnim(s.player,'attack',.34);const v=cameraVectors(s),tx=s.player.x+v.forward.x*1.05,tz=s.player.z+v.forward.z*1.05;s.projectiles.push({owner:'player',kind:'prism-bolt',x:tx,y:1.08,z:tz,vx:v.forward.x*19,vz:v.forward.z*19,life:1.10,damage:34,color:[.40,.95,1],size:.18});burst(s,tx,1.08,tz,[.40,.95,1],7)}
  function ability(s,index){if(index===0)return basicAttack(s);if(s.paused)return;if(index===1){const e=nearestWild(s,13);if(!e){feed(s,'Nenhum alvo para a Rajada.');return}if(s.player.attackCd>0)return;s.player.attackCd=.62;playAnim(s.player,'cast',.62);const a=Math.atan2(e.x-s.player.x,e.z-s.player.z);for(let i=-1;i<=1;i++)s.projectiles.push({owner:'player',x:s.player.x,y:1.05,z:s.player.z,vx:Math.sin(a+i*.14)*15,vz:Math.cos(a+i*.14)*15,life:.85,damage:22,color:[.27,.75,1],size:.13});return}if(index===2){const e=nearestWild(s,10);if(e){damageWild(s,e,12);burst(s,e.x,1,e.z,[.75,.45,1],12)}else feed(s,'O Pulso precisa de uma criatura próxima.');return}if(index===3){const e=nearestWild(s,12);if(e){damageWild(s,e,38);burst(s,e.x,1,e.z,[.62,.22,1],16)}else feed(s,'A Eclipse não encontrou alvo.')}} 
  function harvest(s){const n=nearestNode(s);if(!n){feed(s,'Aproxime-se de um recurso para coletar.');return}if(s.player.attackCd>0)return;s.player.attackCd=.38;playAnim(s.player,'work',.38);n.hp-=35;floatText(s,'-'+35,n.x,1.4,n.z,[.70,1,.82]);burst(s,n.x,.6,n.z,biomeAt(n.x,n.z).accent,3);if(n.hp<=0){const gain=resourceAmount(n.kind);addInv(s,gain);feed(s,'Coletado: '+Object.keys(gain).map(k=>gain[k]+' '+k).join(', '));n.active=false;n.respawn=24;saveProgress(s)}}
  function eat(s){if((s.inv.food||0)>0){s.inv.food--;s.hunger=clamp(s.hunger+32,0,100);s.hydration=clamp(s.hydration+18,0,100);feed(s,'Refeição consumida • fome e hidratação recuperadas.');return}if((s.inv.berry||0)>=2){s.inv.berry-=2;s.hunger=clamp(s.hunger+14,0,100);s.hydration=clamp(s.hydration+8,0,100);feed(s,'Frutas silvestres consumidas.');return}feed(s,'Você não tem comida.')}

  function capture(s){if(s.paused)return;const e=nearestWild(s,9.5);if(!e){feed(s,'Aproxime-se de um monstrinho para capturá-lo.');return}if((s.inv.capsules||0)<=0){feed(s,'Sem Cápsulas Prismáticas. Fabrique mais na bancada.');return}if(e.hp/e.maxHp>.78){feed(s,'Enfraqueça a criatura antes de lançar a cápsula.');return}s.inv.capsules--;playAnim(s.player,'cast',.62);s.captureOrbs.push({target:e.id,x:s.player.x,z:s.player.z,sx:s.player.x,sz:s.player.z,tx:e.x,tz:e.z,life:.62,max:.62});feed(s,'Cápsula lançada em '+CREATURES[e.type].name+'...')}
  function resolveCapture(s,o){const e=s.world.wild.find(x=>x.id===o.target);if(!e||e.dead)return;const chance=clamp(.28+(1-e.hp/e.maxHp)*.72,0,.94);if(Math.random()<chance){e.dead=true;e.captured=true;e.deathTimer=.55;playAnim(e,'death',.55);const d=CREATURES[e.type],id='pet-'+e.id;s.roster.push({id:id,species:e.type,level:Math.max(1,s.level),hp:d.hp,maxHp:d.hp,work:d.work,assigned:false,deployed:true});if(!s.activeCreatureId)s.activeCreatureId=id;xp(s,35);s.tutorial.capture=true;feed(s,'Capturado: '+d.name+' • pressione R para companheiro');burst(s,e.x,1,e.z,[.45,.95,1],18);saveProgress(s)}else{e.hp=Math.min(e.maxHp,e.hp+e.maxHp*.12);feed(s,'A cápsula falhou. A criatura ficou alerta.');burst(s,e.x,1,e.z,[1,.35,.45],8)}}

  function build(s,type){if(!BUILDINGS[type])return;if(type==='baseCore'&&s.base){feed(s,'Você já possui um Núcleo de Base.');return}if(type!=='baseCore'&&!s.base){feed(s,'Construa primeiro o Núcleo de Base.');return}const cost=BUILDINGS[type].cost;if(!hasCost(s,cost)){feed(s,'Materiais insuficientes: '+costText(cost));return}let x=s.player.x,z=s.player.z;if(type!=='baseCore'){const v=cameraVectors(s);x+=v.forward.x*3.2;z+=v.forward.z*3.2;if(dist(x,z,s.base.x,s.base.z)>s.base.radius){feed(s,'Construa dentro do território da base.');return}}spend(s,cost);const b={id:'build-'+Date.now()+'-'+Math.random().toString(16).slice(2),type:type,x:x,z:z,yaw:s.player.yaw||0,hp:100};s.world.structures.push(b);if(type==='baseCore'){s.base={x:x,z:z,radius:21};s.tutorial.base=true;feed(s,'Núcleo de Base estabelecido. Agora construa uma bancada.')}else feed(s,BUILDINGS[type].name+' construída.');s.buildOpen=false;s.paused=false;saveProgress(s);burst(s,x,.4,z,[.35,.90,1],12)}
