  function updateSurvival(s,dt){s.survivalClock+=dt;if(s.survivalClock>=1){s.survivalClock-=1;s.hunger=clamp(s.hunger-.16,0,100);s.hydration=clamp(s.hydration-.22,0,100);if(s.hunger<=0||s.hydration<=0)damagePlayer(s,3)}s.dayClock+=dt*.012;if(s.dayClock>=1){s.dayClock-=1;s.day++;feed(s,'Dia '+s.day+' começou.');saveProgress(s)}const nearFire=structureNear(s,'campfire',4);if(nearFire)s.energy=clamp(s.energy+dt*5,0,100)}
