  function companionObject(s){if(s.activeCreatureId){const r=s.roster.find(x=>x.id===s.activeCreatureId);if(r&&r.deployed!==false)return{type:r.species,x:r.x||s.player.x-2,z:r.z||s.player.z+2,yaw:r.yaw||0,hp:r.hp||CREATURES[r.species].hp,maxHp:r.maxHp||CREATURES[r.species].hp,anim:r.anim||'idle',animT:r.animT||0,animLock:r.animLock||0,attackCd:r.attackCd||1.1,flash:0,roster:r}}if(s.ally.deployed)return s.ally;return null}
  function updateCompanion(s,dt){const a=companionObject(s);if(!a)return;const d=CREATURES[a.type],to=dist(a.x,a.z,s.player.x,s.player.z);if(to>3.1){const ang=Math.atan2(s.player.x-a.x,s.player.z-a.z),sp=d.speed*.92;a.yaw=ang;a.x+=Math.sin(ang)*sp*dt;a.z+=Math.cos(ang)*sp*dt;playAnim(a,to>7?'run':'walk',0)}else if(a.anim==='walk'||a.anim==='run')playAnim(a,'idle',0);a.attackCd=(a.attackCd||0)-dt;const e=nearestAt(s.world.wild,a.x,a.z,10);if(e&&a.attackCd<=0){a.attackCd=1.35;const ang=Math.atan2(e.x-a.x,e.z-a.z);playAnim(a,'cast',.45);s.projectiles.push({owner:'ally',x:a.x,y:1.15,z:a.z,vx:Math.sin(ang)*11,vz:Math.cos(ang)*11,life:1.3,damage:d.atk,color:d.accent,size:.14})}stepAnim(a,dt);if(a.roster){a.roster.x=a.x;a.roster.z=a.z;a.roster.yaw=a.yaw;a.roster.anim=a.anim;a.roster.animT=a.animT;a.roster.animLock=a.animLock;a.roster.attackCd=a.attackCd}}
  function update(s,dt){if(s.paused)return;s.clock+=dt;s.saveClock+=dt;s.player.attackCd=Math.max(0,s.player.attackCd-dt);s.player.dodgeCd=Math.max(0,s.player.dodgeCd-dt);s.player.flash=Math.max(0,s.player.flash-dt);if(!s.player.animLock){const k=s.keys,v=cameraVectors(s);let dx=0,dz=0;if(k.KeyW||k.ArrowUp){dx+=v.forward.x;dz+=v.forward.z}if(k.KeyS||k.ArrowDown){dx-=v.forward.x;dz-=v.forward.z}if(k.KeyD||k.ArrowRight){dx+=v.right.x;dz+=v.right.z}if(k.KeyA||k.ArrowLeft){dx-=v.right.x;dz-=v.right.z}if(dx||dz){s.player.anim=k.ShiftLeft||k.ShiftRight?'run':'walk';move(s,dx,dz,dt);if(s.player.anim==='run')s.energy=clamp(s.energy-dt*9,0,100);else s.energy=clamp(s.energy+dt*4,0,100)}else{s.energy=clamp(s.energy+dt*7,0,100);if(s.player.anim==='walk'||s.player.anim==='run')playAnim(s.player,'idle',0)}}stepAnim(s.player,dt);updateSurvival(s,dt);updateNodes(s,dt);updateProjectiles(s,dt);updateCapture(s,dt);s.world.wild.forEach(e=>updateEnemy(s,e,dt));updateCompanion(s,dt);s.workerClock+=dt;if(s.workerClock>6){s.workerClock=0;workerTick(s)}if(s.saveClock>8){s.saveClock=0;saveProgress(s)}s.particles.forEach(p=>{p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.z+=p.vz*dt;p.vy-=4*dt});s.particles=s.particles.filter(p=>p.life>0);s.floaters.forEach(f=>{f.life-=dt;f.y+=dt*.5});s.floaters=s.floaters.filter(f=>f.life>0);s.feed.forEach(x=>x.life-=dt);s.feed=s.feed.filter(x=>x.life>0)}

